getPSDETreeNodeDataItems.scriptCode:
const app = ibiz.hub.getApp(context.srfappid);
const dataItems = await app.codeList.get(
  'plmweb.ai__file_type',
  context
);
const item = dataItems.find(x => x.value === data.file_type);
if (item && item.sysImage) {
    return item.sysImage.rawContent;
}

const app = ibiz.hub.getApp(context.srfappid);
const dataItems = await app.codeList.get(
  'plmweb.ai__slice_status',
  context
);
const item = dataItems.find(x => x.value === data.status);
if (item && item.sysImage) {
return '<div style="display: flex; align-items: center;justify-content: space-between">'+
    '<div style="overflow: hidden;text-overflow: ellipsis;">'+data.name+'</div>'+
    '<div class="ibiz-code-list__item"><div class="ibiz-icon">'+item.sysImage.rawContent+'</div>'+item.text+'</div>'+
    ' </div>'
}
return data.name;
